//! Generator options of the Rust target: derives added globally or per type
//! (beyond10x/ess#657), an explicit `null` decoded as a missing member (beyond10x/ess#667) and
//! an open object decoded without its unknown members (beyond10x/ess#668). Every option is off
//! by default, and without them the generated bytes are the ones generated before they existed.
//!
//! Nothing here builds the generated crate. `fold_null_decodes_null_as_absent` and
//! `drop_unknown_members_has_no_extra_field`, which decode with it, and the added derives in a
//! built crate are in `model_ergonomics.rs`, the test file allowed to run cargo.

#[allow(dead_code)]
#[path = "fixtures/normalization_model.rs"]
mod model;

#[allow(dead_code)]
#[path = "fixtures/rust_generator_options.rs"]
mod options;

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;

use schema_contract::realize::{Plan, Realization, RustDerive, RustOptions};
use serde_json::json;
use sha2::{Digest, Sha256};

use options::{bundle_plan, declarations, derive_lines, open_schemas, shop_plan, LAB};

/// The SHA-256 of every generated file, with the generator's own version taken out of the
/// declarations' first line and the report, so a release bump does not move it.
fn digest(realization: &Realization) -> String {
    let version = env!("CARGO_PKG_VERSION");
    let declarations =
        realization
            .declarations
            .replacen(&format!("ESS {version};"), "ESS <version>;", 1);
    let mut report = serde_json::to_value(&realization.report).unwrap();
    report["generator_version"] = json!("<version>");
    let mut hasher = Sha256::new();
    for part in [
        declarations.as_str(),
        &serde_json::to_string_pretty(&report).unwrap(),
        &realization.supporting["Cargo.toml"],
    ] {
        hasher.update(part.len().to_le_bytes());
        hasher.update(part.as_bytes());
    }
    hasher
        .finalize()
        .iter()
        .fold(String::new(), |mut hex, byte| {
            write!(hex, "{byte:02x}").unwrap();
            hex
        })
}

/// The digests of the model and bundle realizations generated before any option existed; the
/// model one refrozen for beyond10x/ess#658, where `probe.shop.Colour` names its variants `Blue`
/// and `Red` rather than `V0` and `V1`.
const SHOP_DIGEST: &str = "0c5dfad0170a99263c77c89b0a5ef1f8d05eee6bb830bc7cbcda372a0244aee1";
const OPEN_DIGEST: &str = "85d92b4b6ce765083606c7b9f54495d1609d5c979bad4f656a1ce01c60ce83c4";

fn findings(error: &schema_contract::realize::Refused) -> Vec<(String, String, String)> {
    error
        .0
        .iter()
        .map(|finding| {
            (
                finding.pointer.clone(),
                finding.rule.clone(),
                finding.detail.clone(),
            )
        })
        .collect()
}

#[test]
fn no_option_keeps_the_bytes() {
    let plan = shop_plan();
    for realization in [
        plan.rust("shop_types").unwrap(),
        plan.rust_with("shop_types", &RustOptions::default())
            .unwrap(),
    ] {
        assert_eq!(
            digest(&realization),
            SHOP_DIGEST,
            "{}",
            realization.declarations
        );
    }
}

#[test]
fn defaults_are_unchanged() {
    let plan = bundle_plan(&open_schemas());
    for realization in [
        plan.rust("open_types").unwrap(),
        plan.rust_with("open_types", &RustOptions::default())
            .unwrap(),
    ] {
        assert_eq!(
            digest(&realization),
            OPEN_DIGEST,
            "{}",
            realization.declarations
        );
    }
}

#[test]
fn a_global_derive_is_added_to_every_type() {
    let options = RustOptions {
        derives: BTreeSet::from([RustDerive::Hash]),
        ..RustOptions::default()
    };
    let realization = shop_plan().rust_with("shop_types", &options).unwrap();
    let declarations = declarations(&realization);
    assert!(declarations.len() >= 8, "{declarations:?}");
    for (name, block) in &declarations {
        let lines = derive_lines(block);
        assert_eq!(lines.len(), 1, "{name}: {block}");
        assert!(lines[0].contains("::std::hash::Hash"), "{name}: {block}");
    }
}

#[test]
fn a_per_type_derive_is_added_to_that_type_only() {
    let options = RustOptions {
        type_derives: BTreeMap::from([(
            "probe.shop.Sku".to_owned(),
            BTreeSet::from([RustDerive::Eq, RustDerive::Hash]),
        )]),
        ..RustOptions::default()
    };
    let realization = shop_plan().rust_with("shop_types", &options).unwrap();
    for (name, block) in declarations(&realization) {
        let derives = derive_lines(&block).join("\n");
        let added = derives.contains("::std::cmp::Eq") || derives.contains("::std::hash::Hash");
        assert_eq!(added, name == "ProbeShopSku", "{name}: {block}");
    }
    let unknown = RustOptions {
        type_derives: BTreeMap::from([(
            "probe.shop.Missing".to_owned(),
            BTreeSet::from([RustDerive::Hash]),
        )]),
        ..RustOptions::default()
    };
    let refused = shop_plan().rust_with("shop_types", &unknown).unwrap_err();
    assert_eq!(
        findings(&refused)
            .into_iter()
            .map(|(pointer, rule, _)| (pointer, rule))
            .collect::<Vec<_>>(),
        [("/".to_owned(), "rust_derive".to_owned())],
        "{refused:?}"
    );
}

#[test]
fn an_unsatisfiable_derive_is_refused_by_name() {
    let plan = Plan::from_model(&model::selection(LAB, &["probe.lab.Reading"])).unwrap();
    let options = RustOptions {
        derives: BTreeSet::from([RustDerive::Eq]),
        ..RustOptions::default()
    };
    let refused = findings(&plan.rust_with("lab_types", &options).unwrap_err());
    assert_eq!(refused.len(), 1, "{refused:?}");
    let (pointer, rule, detail) = &refused[0];
    assert_eq!(pointer, "/$defs/probe.lab.Reading/properties/ratio");
    assert_eq!(rule, "rust_derive_unsatisfied");
    for named in ["ProbeLabReading", "`ratio`", "Eq", "EssBinary64"] {
        assert!(detail.contains(named), "{named} in {detail}");
    }

    // `Default` on an enum is refused naming the enum; a struct holding it, naming its field.
    let options = RustOptions {
        type_derives: BTreeMap::from([
            (
                "probe.shop.Colour".to_owned(),
                BTreeSet::from([RustDerive::Default]),
            ),
            (
                "probe.shop.Line".to_owned(),
                BTreeSet::from([RustDerive::Hash]),
            ),
        ]),
        ..RustOptions::default()
    };
    let refused = findings(&shop_plan().rust_with("shop_types", &options).unwrap_err());
    let colour = refused
        .iter()
        .find(|(pointer, ..)| pointer == "/$defs/probe.shop.Colour")
        .unwrap_or_else(|| panic!("{refused:?}"));
    assert_eq!(colour.1, "rust_derive_unsatisfied");
    assert!(
        colour.2.contains("ProbeShopColour") && colour.2.contains("Default"),
        "{colour:?}"
    );
    let sku = refused
        .iter()
        .find(|(pointer, ..)| pointer == "/$defs/probe.shop.Line/properties/sku")
        .unwrap_or_else(|| panic!("{refused:?}"));
    for named in ["ProbeShopLine", "`sku`", "ProbeShopSku", "Hash"] {
        assert!(sku.2.contains(named), "{named} in {sku:?}");
    }

    // `Ord` needs `Eq` and `PartialOrd` beside it.
    let options = RustOptions {
        derives: BTreeSet::from([RustDerive::Ord]),
        ..RustOptions::default()
    };
    let refused = findings(&shop_plan().rust_with("shop_types", &options).unwrap_err());
    assert_eq!(
        refused,
        [(
            "/".to_owned(),
            "rust_derive".to_owned(),
            "Ord needs Eq and PartialOrd beside it".to_owned()
        )]
    );
}

#[test]
fn the_report_records_each_option() {
    let options = RustOptions {
        derives: BTreeSet::from([RustDerive::Hash]),
        type_derives: BTreeMap::from([("Map".to_owned(), BTreeSet::from([RustDerive::Eq]))]),
        fold_null: true,
        drop_unknown_members: true,
    };
    let realization = bundle_plan(&open_schemas())
        .rust_with("open_types", &options)
        .unwrap();
    let report = serde_json::to_value(&realization.report).unwrap();
    assert_eq!(
        report["configuration"],
        json!({
            "language": "rust",
            "package": "open_types",
            "derives": ["Hash"],
            "type_derives": {"Map": ["Eq"]},
            "fold_null": true,
            "drop_unknown_members": true
        })
    );
    let obligations = report["obligations"]
        .as_array()
        .unwrap()
        .iter()
        .map(|finding| {
            (
                finding["rule"].as_str().unwrap(),
                finding["pointer"].as_str().unwrap(),
            )
        })
        .collect::<BTreeSet<_>>();
    for expected in [
        ("rust_fold_null", "/components/schemas/Open/properties/x"),
        ("rust_fold_null", "/components/schemas/Closed/properties/y"),
        ("rust_drop_unknown_members", "/components/schemas/Open"),
        ("rust_drop_unknown_members", "/components/schemas/Counted"),
        ("open_object_storage", "/components/schemas/Map"),
    ] {
        assert!(
            obligations.contains(&expected),
            "{expected:?} in {obligations:?}"
        );
    }
    for absent in [
        ("open_object_storage", "/components/schemas/Open"),
        ("open_object_storage", "/components/schemas/Counted"),
        ("rust_drop_unknown_members", "/components/schemas/Map"),
    ] {
        assert!(
            !obligations.contains(&absent),
            "{absent:?} in {obligations:?}"
        );
    }
}
